mapper.select:
where del_flag = 0 and tier = #{tier} and account_id = #{accountId}
and exists (select 1 from crm_contact c where c.contact_id = crm_patient_value.contact_id and c.original_source = #{originalSource})
and net_clv >= #{minNetClv} and net_clv <= #{maxNetClv}
and last_visit_at is not null and EXTRACT(day FROM (CURRENT_TIMESTAMP - last_visit_at)) >= #{daysSinceLastVisitGte}
and COALESCE(implant_total, 0) > 0 and COALESCE(ortho_total, 0) > 0 and COALESCE(restorative_total, 0) > 0 and COALESCE(preventive_total, 0) > 0 and COALESCE(pediatric_total, 0) > 0
and exists (select 1 from crm_contact c where c.contact_id = crm_patient_value.contact_id and c.owner = #{owner})
and exists (select 1 from crm_contact c where c.contact_id = crm_patient_value.contact_id and c.org_id = #{orgId})
order by pltv_12m order by last_visit_at order by net_clv
asc desc


where del_flag = 0 and next_recall_due_at is not null and next_recall_due_at <= CURRENT_TIMESTAMP
order by next_recall_due_at
limit #{limit}
